Tile("hello-there", {
  css: ".hi{display:flex;flex-direction:column;justify-content:center;height:100%} .hi b{font-size:44px;color:var(--accent)} .hi small{color:var(--dim);font-size:20px}",
  cls: "hi",
  render(el){
    const t = new Date();
    el.innerHTML = "<b>Hello there</b><div>" + this.esc(t.toLocaleTimeString([], {hour:"numeric", minute:"2-digit"})) + "</div><small>Version 1</small>";
  }
});
